# PTX source for L2‑normalization along dimension 1 (float16 tensors)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry l2norm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 dim
)
{
    // ---------- registers ----------
    .reg .pred   %p<6>;
    .reg .b32    %r<12>;
    .reg .b64    %rd<13>;
    .reg .f32    %f<8>;
    .reg .f16    %h<2>;

    // ---------- shared memory ----------
    .shared .align 4 .b32 block_sum;   // holds the per‑block sum of squares

    // ---------- load kernel parameters ----------
    ld.param.u64 %rd1, [x_ptr];   // input base pointer
    ld.param.u64 %rd2, [y_ptr];   // output base pointer
    ld.param.u32 %r1,  [dim];     // dim (size of the normalization axis)

    // ---------- thread / block identifiers ----------
    mov.u32 %r2, %tid.x;         // threadIdx.x
    mov.u32 %r3, %ctaid.x;       // blockIdx.x   (row index)
    mov.u32 %r4, %ntid.x;        // blockDim.x

    // ---------- compute row base addresses ----------
    cvt.u64.u32 %rd3, %r3;               // row index as 64‑bit
    mul.lo.u64 %rd4, %rd3, %r1;          // row * dim   (elements)
    mul.wide.u32 %rd5, %rd4, 2;          // *2 bytes per half‑precision element
    add.u64 %rd6, %rd1, %rd5;            // input row base address
    add.u64 %rd7, %rd2, %rd5;            // output row base address

    // ---------- first pass: compute sum of squares ----------
    mov.f32 %f1, 0f0;                    // partial sum for this thread
    mov.u32 %r5, %r2;                    // i = threadIdx.x

LOOP_SUM:
    setp.ge.u32 %p1, %r5, %r1;           // if i >= dim -> exit
    @%p1 bra END_LOOP_SUM;

    // load half‑precision element
    mul.wide.u32 %rd8, %r5, 2;           // offset = i * 2
    add.u64 %rd9, %rd6, %rd8;            // address = base + offset
    ld.global.u16 %h1, [%rd9];

    // convert to float, square, accumulate
    cvt.f32.f16 %f2, %h1;
    mul.f32 %f2, %f2, %f2;
    add.f32 %f1, %f1, %f2;

    // i += blockDim.x
    add.u32 %r5, %r5, %r4;
    bra LOOP_SUM;
END_LOOP_SUM:

    // ---------- initialize block_sum (once per block) ----------
    setp.eq.u32 %p2, %r2, 0;
    @%p2 {
        mov.f32 %f3, 0f0;
        st.shared.f32 [block_sum], %f3;
    }
    bar.sync 0;

    // ---------- atomic accumulation of partial sums ----------
    atom.add.shared.f32 [block_sum], %f1;
    bar.sync 0;

    // ---------- broadcast total sum to all threads ----------
    setp.eq.u32 %p3, %r2, 0;
    @%p3 ld.shared.f32 %f4, [block_sum];   // thread 0 loads total
    mov.f32 %f5, %f4;                       // broadcast (register copy)
    // (all threads now have the same value in %f5)

    // ---------- compute 1 / sqrt(total) ----------
    rsqrt.approx.f32 %f6, %f5;              // f6 = 1 / sqrt(total)

    // ---------- second pass: write normalized output ----------
    mov.u32 %r6, %r2;                       // i = threadIdx.x again

LOOP_OUT:
    setp.ge.u32 %p4, %r6, %r1;
    @%p4 bra END_LOOP_OUT;

    mul.wide.u32 %rd10, %r6, 2;             // offset = i * 2
    add.u64 %rd11, %rd6, %rd10;            // input address
    ld.global.u16 %h2, [%rd11];
    cvt.f32.f16 %f7, %h2;
    mul.f32 %f7, %f7, %f6;                 // multiply by 1/sqrt
    cvt.f16.f32 %h2, %f7;                  // back to half

    add.u64 %rd12, %rd7, %rd10;            // output address
    st.global.u16 [%rd12], %h2;

    add.u32 %r6, %r6, %r4;                 // i += blockDim.x
    bra LOOP_OUT;
END_LOOP_OUT:
    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load PTX module using the harness-provided helper
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        # x is expected to be a CUDA tensor of dtype torch.float16
        batch, dim = x.shape
        out = torch.empty_like(x)

        # Choose a reasonable block size (must be power‑of‑two and <=1024)
        block = (256, 1, 1)          # 256 threads per block
        grid  = (batch, 1, 1)        # one block per row

        # Arguments: input ptr, output ptr, dim (int)
        args = [x.data_ptr(), out.data_ptr(), dim]

        # Launch the kernel via the harness
        ptx_launch(self.module, "l2norm_kernel", grid, block, args)

        return out
